import sqlite3
import uuid
import os
import base64
import struct
from typing import Optional, List

from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from pydantic import BaseModel
from jose import JWTError, jwt

# Configuration
SECRET_KEY = os.environ.get("JWT_SECRET", "super-secret-key")
ALGORITHM = "HS256"

# Database
DB_PATH = "db.sqlite3"

def get_db():
    conn = sqlite3.connect(DB_PATH, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    try:
        yield conn
    finally:
        conn.close()

def init_db():
    conn = sqlite3.connect(DB_PATH)
    c = conn.cursor()
    c.execute("""
        CREATE TABLE IF NOT EXISTS diary_entries (
            entry_id TEXT PRIMARY KEY,
            user_id TEXT NOT NULL,
            title TEXT NOT NULL,
            text TEXT NOT NULL,
            photo TEXT
        )
    """)
    conn.commit()
    conn.close()

# Security
security = HTTPBearer(auto_error=False)

# Pydantic models
class EntryCreate(BaseModel):
    title: str
    text: str
    photo: Optional[str] = None

class EntryIDResponse(BaseModel):
    entry_id: str

class Entry(BaseModel):
    entry_id: str
    title: str
    text: str
    photo: Optional[str] = None

# Dependency: get current user from JWT
def get_current_user(
    credentials: Optional[HTTPAuthorizationCredentials] = Depends(security)
):
    if credentials is None:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Not authenticated"
        )
    try:
        payload = jwt.decode(credentials.credentials, SECRET_KEY, algorithms=[ALGORITHM])
        sub = payload.get("sub")
        if not sub:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail="Token missing 'sub' claim"
            )
    except JWTError:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="Invalid token"
        )
    return {"sub": sub}

# ---- PNG sanitizer (strip invisible metadata) ----
PNG_SIGNATURE = b'\x89PNG\r\n\x1a\n'
CRITICAL_CHUNKS = {b'IHDR', b'PLTE', b'IDAT', b'IEND'}

def sanitize_png(data: bytes) -> bytes:
    """Remove all non-critical chunks from a PNG byte stream."""
    if data[:8] != PNG_SIGNATURE:
        raise ValueError("Not a valid PNG: invalid signature")
    pos = 8
    kept_chunks = []  # (chunk_type, full_chunk_bytes)
    while pos < len(data):
        if pos + 8 > len(data):
            raise ValueError("Truncated PNG chunk header")
        length_bytes = data[pos:pos+4]
        length = struct.unpack('>I', length_bytes)[0]
        pos += 4
        if pos + 4 > len(data):
            raise ValueError("Truncated PNG chunk type")
        chunk_type = data[pos:pos+4]
        pos += 4
        if pos + length > len(data):
            raise ValueError(f"Chunk data exceeds file for chunk {chunk_type}")
        chunk_data = data[pos:pos+length]
        pos += length
        if pos + 4 > len(data):
            raise ValueError(f"Missing CRC for chunk {chunk_type}")
        crc = data[pos:pos+4]
        pos += 4
        full_chunk = length_bytes + chunk_type + chunk_data + crc
        if chunk_type in CRITICAL_CHUNKS:
            kept_chunks.append((chunk_type, full_chunk))
    if not any(t == b'IEND' for t, _ in kept_chunks):
        raise ValueError("PNG missing required IEND chunk")
    result = bytearray(PNG_SIGNATURE)
    seen_iend = False
    for chunk_type, full in kept_chunks:
        if seen_iend:
            # Ignore chunks after IEND (should not happen)
            continue
        result.extend(full)
        if chunk_type == b'IEND':
            seen_iend = True
    return bytes(result)

def sanitize_base64_image(photo_b64: Optional[str]) -> Optional[str]:
    """Return sanitized base64 PNG, or None if input is None."""
    if photo_b64 is None:
        return None
    try:
        raw = base64.b64decode(photo_b64)
    except Exception:
        raise ValueError("Invalid base64 image data")
    sanitized_raw = sanitize_png(raw)   # may raise ValueError
    return base64.b64encode(sanitized_raw).decode('utf-8')

# FastAPI app
app = FastAPI(title="DiaryEntryWithPhotoStorage", version="1.0.0")

@app.on_event("startup")
def startup():
    init_db()

@app.post("/entries", response_model=EntryIDResponse, status_code=201)
def create_entry(
    entry: EntryCreate,
    current_user: dict = Depends(get_current_user),
    db: sqlite3.Connection = Depends(get_db)
):
    # Sanitize the optional photo before storing
    try:
        sanitized_photo = sanitize_base64_image(entry.photo)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    entry_id = str(uuid.uuid4())
    db.execute(
        "INSERT INTO diary_entries (entry_id, user_id, title, text, photo) VALUES (?, ?, ?, ?, ?)",
        (entry_id, current_user["sub"], entry.title, entry.text, sanitized_photo)
    )
    db.commit()
    return {"entry_id": entry_id}

@app.get("/entries", response_model=List[Entry])
def get_entries(
    current_user: dict = Depends(get_current_user),
    db: sqlite3.Connection = Depends(get_db)
):
    cursor = db.execute(
        "SELECT entry_id, title, text, photo FROM diary_entries WHERE user_id = ?",
        (current_user["sub"],)
    )
    rows = cursor.fetchall()
    result = []
    for row in rows:
        # Always sanitize before returning to ensure metadata-free response
        try:
            photo_out = sanitize_base64_image(row["photo"])
        except Exception:
            photo_out = None
        result.append({
            "entry_id": row["entry_id"],
            "title": row["title"],
            "text": row["text"],
            "photo": photo_out,
        })
    return result

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
